import { Block, Text } from "@prototyp/skeletor";
import type { NativeStackScreenProps } from "@react-navigation/native-stack";
import { FlashList } from "@shopify/flash-list";
import type {
  EventTimelineItem,
  RoomInterface,
  TaskHandleInterface,
} from "@unomed/react-native-matrix-sdk";
import {
  DateDividerMode,
  TimelineDiff_Tags,
  TimelineFilter,
  TimelineFocus,
  TimelineReadReceiptTracking,
} from "@unomed/react-native-matrix-sdk";
import { getEventId } from "modules/matrix-client/utils";
import { type FC, useEffect, useState } from "react";
import { StyleSheet } from "react-native";
import { SingleMessageType } from "screens/room/fragments";
import { GoBackHeader, Loading } from "shared/components";
import { ScreenLayout } from "shared/components/screen-layout/ScreenLayout";
import { Colors, TextSize } from "shared/styles";

const keyExtractor = (item: EventTimelineItem) => {
  const eventId = item.eventOrTransactionId;
  if (eventId?.tag === "EventId") {
    return eventId.inner.eventId;
  }
  if (eventId?.tag === "TransactionId") {
    return eventId.inner.transactionId;
  }
  return String(item.timestamp);
};

/**
 * Fetches a single event by ID using a temporary Event-focused timeline.
 * This works around the PinnedEvents focus returning empty results
 * by loading each event directly from the server.
 */
const fetchEventById = (
  room: RoomInterface,
  eventId: string,
): Promise<EventTimelineItem | null> => {
  return new Promise(async (resolve) => {
    let handle: TaskHandleInterface | null = null;
    let resolved = false;

    const cleanup = () => {
      if (!resolved) {
        resolved = true;
        handle?.cancel?.();
      }
    };

    const timeout = setTimeout(() => {
      cleanup();
      resolve(null);
    }, 10000);

    try {
      const timeline = await room.timelineWithConfiguration({
        focus: new TimelineFocus.Event({
          eventId,
          numContextEvents: 0,
          hideThreadedEvents: false,
        }),
        filter: new TimelineFilter.All(),
        internalIdPrefix: `pin_${eventId.slice(-8)}_`,
        dateDividerMode: DateDividerMode.Daily,
        trackReadReceipts: TimelineReadReceiptTracking.Disabled,
        reportUtds: false,
      });

      handle = await timeline.addListener({
        onUpdate: (diffs) => {
          if (resolved) return;

          for (const diff of diffs) {
            const items =
              diff.tag === TimelineDiff_Tags.Reset ||
              diff.tag === TimelineDiff_Tags.Append
                ? diff.inner.values
                : diff.tag === TimelineDiff_Tags.PushBack ||
                    diff.tag === TimelineDiff_Tags.PushFront ||
                    diff.tag === TimelineDiff_Tags.Insert ||
                    diff.tag === TimelineDiff_Tags.Set
                  ? [diff.inner.value]
                  : [];

            for (const item of items) {
              const ev = item.asEvent?.() ?? item.asEvent?.();
              if (ev && getEventId(ev) === eventId) {
                clearTimeout(timeout);
                cleanup();
                resolve(ev);
                return;
              }
            }
          }
        },
      });
    } catch (error) {
      console.warn("[PinnedEvents] Failed to fetch event:", eventId, error);
      clearTimeout(timeout);
      cleanup();
      resolve(null);
    }
  });
};

export const PinnedEvents: FC<
  NativeStackScreenProps<Routes, "pinnedEvents">
> = ({ route }) => {
  const { room } = route.params;
  const [events, setEvents] = useState<EventTimelineItem[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (!room) return;

    setLoading(true);
    setEvents([]);
    let cancelled = false;

    const loadPinnedEvents = async () => {
      try {
        const roomInfo = await room.roomInfo();
        const pinnedIds = roomInfo.pinnedEventIds || [];
        console.log("[PinnedEvents] pinnedEventIds from roomInfo:", pinnedIds);

        if (pinnedIds.length === 0) {
          setLoading(false);
          return;
        }

        const fetchedEvents: EventTimelineItem[] = [];

        for (const id of pinnedIds) {
          if (cancelled) break;
          try {
            const event = await fetchEventById(room, id);
            if (event) fetchedEvents.push(event);
          } catch (error) {
            console.warn("[PinnedEvents] Failed to load event:", id, error);
          }
        }

        if (!cancelled) {
          setEvents(
            fetchedEvents.sort(
              (a, b) => Number(b.timestamp) - Number(a.timestamp),
            ),
          );
          setLoading(false);
        }
      } catch (error) {
        console.error("[PinnedEvents] Failed to load pinned events:", error);
        if (!cancelled) setLoading(false);
      }
    };

    loadPinnedEvents();

    return () => {
      cancelled = true;
    };
  }, [room]);

  return (
    <ScreenLayout type="modal">
      <GoBackHeader title="Pinned Events" margins={{ marginBottom: 20 }} />
      <FlashList
        data={events}
        renderItem={({ item }) => {
          return (
            <Block paddings={{ paddingHorizontal: 16 }}>
              <SingleMessageType event={item} isPreviousSameSender={false} />
            </Block>
          );
        }}
        keyExtractor={keyExtractor}
        contentContainerStyle={styles.listContent}
        ListEmptyComponent={
          <Block align="center" justify="center" flex={1} paddings={40}>
            {loading ? (
              <Loading isFullScreen={false} />
            ) : (
              <Text size={TextSize.medium} color={Colors.white50}>
                No pinned events
              </Text>
            )}
          </Block>
        }
        showsVerticalScrollIndicator={false}
      />
    </ScreenLayout>
  );
};

const styles = StyleSheet.create({
  listContent: {
    flexGrow: 1,
    paddingBottom: 20,
  },
});
